/* First-review app. Isolated local preferences; no production data writes. */
'use strict';
const D=REVIEW_DATA, byId=(rows)=>new Map(rows.map(x=>[x.id,x]));
const persons=byId(D.members), songs=byId(D.songs), videos=byId(D.videos), albums=byId(D.albums), notices=byId(D.notices), events=byId(D.events), histories=byId(D.history);
const names=Object.fromEntries(D.members.map(m=>[m.id,m.name]));
const types={member:'멤버',notice:'공지',event:'일정',song:'음악',video:'영상',history:'활동',album:'음반'};
const songTypes={original:'오리지널',cover:'커버',remake:'리메이크',official_track:'공식 음원·MV',album_medley:'앨범 메들리',performance:'무대',music_clip:'음악 클립'};
const historyTypes={release:'음악 발매',performance:'공연·행사',content:'주요 콘텐츠',collaboration:'협업',award:'수상',audition:'오디션'};
const sourceNames={'berriz-notice':'베리즈 공식 공지','berriz-calendar':'베리즈 공식 캘린더','cafe-members':'멤버 공지','cafe-agency':'패러블 공지','fan-roundup':'팬 정리 · 미확정','parable-web':'패러블 뉴스룸'};
const paths={spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',sun:'M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',moon:'M20 15a9 9 0 0 1-11-11A9 9 0 1 0 20 15',arrow:'M5 12h14m-5-5 5 5-5 5',back:'M19 12H5m5-5-5 5 5 5',external:'M14 3h7v7M21 3 10 14M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-5',calendar:'M8 2v4M16 2v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2M7 14h2M15 14h2M7 18h2',music:'M9 18V5l12-2v13M9 18a3 3 0 1 1-3-3h3M21 16a3 3 0 1 1-3-3h3M9 9l12-2',video:'m9 5 11 7-11 7Z',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',menu:'M4 6h16M4 12h16M4 18h16',check:'m5 12 4 4L19 6',book:'M12 5v16M12 5C8 2 4 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-3-1-7-2-10 1',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`;
const defaults={theme:'dark',gallery:true,spoilers:false,density:'cards',favorites:[],interests:[],watched:[],notifications:false};
let storageAvailable=true, prefs={...defaults}, previousVisit=null;
try{const p=JSON.parse(localStorage.getItem('isegye:review1:prefs')||'null');if(p&&typeof p==='object')prefs={...defaults,...p};previousVisit=localStorage.getItem('isegye:review1:lastVisit');localStorage.setItem('isegye:review1:lastVisit',new Date().toISOString());}catch{storageAvailable=false;}
prefs.theme=['dark','light'].includes(prefs.theme)?prefs.theme:'dark';prefs.density=['cards','list'].includes(prefs.density)?prefs.density:'cards';
for(const k of ['favorites','interests','watched'])prefs[k]=Array.isArray(prefs[k])?prefs[k].filter(x=>typeof x==='string').slice(0,3000):[];
prefs.interests=prefs.interests.filter(x=>persons.has(x));
for(const k of ['gallery','spoilers','notifications'])prefs[k]=typeof prefs[k]==='boolean'?prefs[k]:defaults[k];
const memberItems=D.members.map(m=>({...m,title:m.name,kind:'member',key:'member:'+m.id,members:[m.id],summary:m.description,tags:[m.en,m.fanName]}));
const allItems=[...memberItems,...D.songs,...D.videos,...D.notices,...D.events,...D.history,...D.albums], registry=new Map(allItems.map(x=>[x.key,x]));
const nowDay=()=>kstDay(new Date().toISOString());
const dateText=s=>s?String(s).slice(0,10).replaceAll('-','.'): '날짜 미확인';
const stamp=s=>{const n=Date.parse(s);return Number.isFinite(n)?new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',dateStyle:'medium',timeStyle:'short'}).format(n)+' KST':'확인 전';};
const memberText=ids=>ids?.length===6?'이세계아이돌':(ids||[]).map(x=>names[x]).filter(Boolean).join(' · ')||'참여자 원문 확인';
const badge=(text,cls='')=>`<span class="badge ${cls}">${esc(text)}</span>`;
const sourceLabel=r=>sourceNames[r.sourceId]||r.channelName||(r.kind==='history'?'공개 출처 기록':'자료 기준 확인');
function itemRoute(r){return '#/'+(r.kind==='member'?'member':r.kind)+'/'+encodeURIComponent(r.id);}
function external(url,text,cls='text-link'){const u=safeExternal(url);return u?`<a class="${cls}" href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(text)} ${icon('external')}</a>`:'';}
function route(){let p;try{p=decodeURI(location.hash.replace(/^#\/?/,'')||'home');}catch{p='not-found';}const [s,q='']=p.split('?');return {parts:s.split('/'),params:new URLSearchParams(q),path:s};}
function url(path,values={}){const q=new URLSearchParams();for(const[k,v]of Object.entries(values))if(v!==null&&v!==undefined&&v!==''&&v!=='all')q.set(k,String(v));return '#/'+path+(q.size?'?'+q:'');}
function patch(patch){const r=route(),q=new URLSearchParams(r.params);for(const[k,v]of Object.entries(patch)){if(v===null||v===undefined||v===''||v==='all')q.delete(k);else q.set(k,String(v));}if(!Object.hasOwn(patch,'page'))q.delete('page');return '#/'+r.path+(q.size?'?'+q:'');}
function selected(p=route().params){return (p.get('members')||p.get('member')||'').split(',').filter(x=>persons.has(x));}
function heading(title,sub,eyebrow='ISEGYE FAN ARCHIVE'){return `<header class="page-heading"><div><p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><span class="date-label">${dateText(nowDay())} · KST</span></header>`;}
function sectionHead(title,sub='',label='',href=''){return `<div class="section-head"><div><h2>${esc(title)}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div>${href?`<a class="text-link" href="${esc(href)}">${esc(label)} ${icon('arrow')}</a>`:''}</div>`;}
function empty(title,sub,href='',label='전체 보기'){return `<div class="empty">${icon('search')}<h3>${esc(title)}</h3><p>${esc(sub)}</p>${href?`<a class="button" href="${esc(href)}">${esc(label)}</a>`:''}</div>`;}
function saveButton(r,masked=false){const on=prefs.favorites.includes(r.key);return `<button class="save" data-save="${esc(r.key)}" aria-pressed="${on}" aria-label="${esc(masked?'가림 영상':r.title)} ${on?'저장 해제':'저장'}">${icon('heart')}<span>${on?'저장됨':'저장'}</span></button>`;}
function memberChips(p=route().params){const ids=selected(p);return `<div class="chips" aria-label="멤버 선택"><a class="chip ${!ids.length?'active':''}" href="${esc(patch({members:null,member:null}))}">전체</a>${D.members.map(m=>`<a class="chip tone-${m.id} ${ids.includes(m.id)?'active':''}" href="${esc(patch({members:ids.includes(m.id)?ids.filter(x=>x!==m.id).join(','):[...ids,m.id].join(','),member:null}))}" aria-label="${m.name} ${ids.includes(m.id)?'선택 해제':'선택'}"><i class="dot"></i>${m.name}</a>`).join('')}</div>`;}
function choose(label,key,options,value){return `<label>${esc(label)}<select data-filter="${key}" aria-label="${esc(label)}">${options.map(([k,v])=>`<option value="${esc(k)}" ${k===value?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;}
function tabs(options,active,key='tab'){return `<nav class="tabbar" aria-label="화면 분류">${options.map(([id,label,count])=>`<a class="tab ${active===id?'active':''}" ${active===id?'aria-current="page"':''} href="${esc(patch({[key]:id,page:null}))}">${esc(label)}${count!==undefined?`<span>${count}</span>`:''}</a>`).join('')}</nav>`;}
function paginate(rows,p,size=24){const max=Math.max(1,Math.ceil(rows.length/size)),page=Math.min(max,Math.max(1,Number(p.get('page'))||1));return {rows:rows.slice((page-1)*size,page*size),html:max>1?`<nav class="pagination" aria-label="목록 페이지">${page>1?`<a class="button" href="${esc(patch({page:page-1}))}">이전</a>`:''}<span>${page} / ${max}</span>${page<max?`<a class="button" href="${esc(patch({page:page+1}))}">다음</a>`:''}</nav>`:'',page};}
function newest(a,b){return String(b.date||'').localeCompare(a.date||'')||String(b.publishedAt||'').localeCompare(a.publishedAt||'')||a.id.localeCompare(b.id);}
function filtered(rows,p){const ids=selected(p),q=p.get('q')||'',from=p.get('from'),to=p.get('to'),year=p.get('year');return rows.filter(r=>memberMatches(r,ids,p.get('match')||'any')&&matchesQuery(r,q,names,new Date().getFullYear())&&(!from||!validDay(from)||(r.date||'')>=from)&&(!to||!validDay(to)||(r.date||'')<=to)&&(!year||year==='all'||r.date?.startsWith(year))).sort(newest);}
function thumb(r){const id=r.kind==='song'?r.videoId:r.id;return `<div class="thumb"><div class="fallback">${icon(r.kind==='song'?'music':'video')}<span>원본 영상에서 확인</span></div>${/^[\w-]{11}$/.test(id||'')?`<img src="https://i.ytimg.com/vi/${id}/mqdefault.jpg" alt="" width="320" height="180" loading="lazy" referrerpolicy="no-referrer" data-thumbnail>`:''}<span class="play-mark">${icon('video')}</span></div>`;}
function mediaCard(r){const masked=prefs.spoilers&&r.kind==='video'&&r.category!=='group';return `<article class="content-card ${masked?'spoiler-masked':''}" data-item-key="${esc(r.key)}"><a href="${esc(itemRoute(r))}" aria-label="${masked?'스포일러 가림 영상 상세':esc(r.title)}">${thumb(r)}</a><div class="card-body"><div class="badges">${badge(types[r.kind])}${badge(r.kind==='song'?(songTypes[r.type]||r.type):(r.format||'영상'),'neutral')}${r.videoSource?.kind==='fan_backup'?badge('팬 백업','warning'):''}${prefs.watched.includes(r.key)?badge('직접 시청 표시','good'):''}</div><a href="${esc(itemRoute(r))}" data-spoiler-title ${masked?'aria-label="가림 영상 상세"':''}><h3 ${masked?'aria-hidden="true"':''}>${esc(r.title)}</h3></a><p>${esc(memberText(r.members))}</p><div class="card-bottom"><span>${dateText(r.date)}${r.kind==='video'?' · '+esc(r.dateLabel||'공개'):''}</span>${saveButton(r,masked)}</div></div>${masked?`<button class="spoiler-reveal" data-reveal>제목·이미지 보기</button>`:''}</article>`;}
function rowCard(r){const kind=r.kind,label=r.kind==='song'?(songTypes[r.type]||'음악'):sourceLabel(r);return `<article class="row-card" data-item-key="${esc(r.key)}"><span class="row-symbol">${icon(kind==='event'?'calendar':kind==='song'?'music':kind==='video'?'video':kind==='member'?'users':'book')}</span><div class="row-copy"><div class="badges">${badge(types[kind]||'자료')}${badge(label,'neutral')}${kind==='event'?badge(r.status==='cancelled'?'취소':r.certainty==='confirmed'?'확정':'미확정',r.status==='cancelled'?'warning':'good'):''}</div><a href="${esc(itemRoute(r))}"><h3>${esc(r.title)}</h3></a><p>${r.date?dateText(r.date)+' · ':''}${kind==='notice'?'게시일 기준 · ':kind==='event'?(r.time?esc(r.time)+' KST · ':'시간 미정 · '):''}${esc(memberText(r.members))}</p></div>${saveButton(r)}</article>`;}
function mediaGrid(rows){return rows.length?`<div class="grid ${prefs.density==='list'?'compact':''}">${rows.map(mediaCard).join('')}</div>`:empty('조건에 맞는 자료가 없어요','다른 조건을 선택해 보세요. 자료가 없다고 활동이 없었다는 뜻은 아닙니다.');}
function seriesCard(s){return `<a class="series-card" href="#/series/${s.id}"><span class="series-icon">${icon('book')}</span><p class="eyebrow">${esc(s.subtitle)}</p><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><span class="text-link">연결된 기록 보기 ${icon('arrow')}</span></a>`;}
let toastTimer;
function toast(t){const x=document.getElementById('toast');x.textContent=t;x.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>x.classList.remove('show'),2800);}
function persist(){try{localStorage.setItem('isegye:review1:prefs',JSON.stringify(prefs));storageAvailable=true;return true;}catch{storageAvailable=false;toast('브라우저 저장을 사용할 수 없어 이 탭에서만 유지됩니다.');return false;}}
const nav=[['home','오늘의 이세돌','spark'],['members','멤버 소개','users'],['schedule','소식·일정','calendar'],['music','음악','music'],['live','LIVE·방송','video'],['history','활동 기록','clock']];
function activeMenu(){const id=route().parts[0];return ({member:'members',record:'members',song:'music',album:'music',video:'live',series:'live',notice:'schedule',event:'schedule'})[id]||id;}
function shell(){const active=activeMenu(),q=route().parts[0]==='search'?route().params.get('q')||'':'';return `<div class="review-bar"><div class="wrap"><b>1차 검토</b><span>운영 사이트와 분리된 미리보기</span><span class="branch-label">· feature/review-1st</span><a href="#/review">적용 범위·검토 안내 ↗</a></div></div><header class="site-header"><div class="wrap masthead"><a class="brand" href="#/home" aria-label="ISEGYE 팬 아카이브 홈"><span class="brand-mark">${icon('spark')}</span><span><strong>ISEGYE!</strong><small>팬 아카이브</small></span></a><p class="tagline">지금의 소식부터,<br>다시 보고 싶은 순간까지.</p><div class="top-actions"><form class="header-search" id="header-search" role="search"><label class="sr-only" for="header-query">통합 검색</label><input id="header-query" name="q" type="search" maxlength="180" value="${esc(q)}" placeholder="멤버·곡·공지·방송 검색" autocomplete="off" enterkeyhint="search"><button type="submit" aria-label="검색">${icon('search')}</button></form><a href="#/saved" class="round-btn" aria-label="저장함">${icon('heart')}<span class="saved-dot" data-save-count>${prefs.favorites.filter(x=>registry.has(x)).length}</span></a><button class="round-btn" data-action="theme" aria-label="색상 테마 변경">${icon(prefs.theme==='dark'?'sun':'moon')}</button></div></div><div class="wrap"><nav class="desktop-nav" aria-label="주 메뉴">${nav.map(([id,label,glyph])=>`<a href="#/${id}" ${active===id?'aria-current="page"':''}>${id==='home'?icon(glyph):''}${label}</a>`).join('')}<span class="nav-tools"><a href="#/guide">팬 가이드</a><a href="#/settings" aria-label="화면 설정">${icon('settings')}</a></span></nav></div></header><main id="main" class="wrap" tabindex="-1"></main><footer class="footer"><div class="wrap"><div><b>이세계아이돌 비공식 팬 프로젝트</b><p>패러블 및 아티스트의 승인·후원·협찬과 관계없습니다.<br>이미지와 원본 콘텐츠의 권리는 각 권리자에게 있습니다.</p><small>© 2026 ISEGYE FAN ARCHIVE · 1차 검토</small></div><nav class="footer-links" aria-label="이용 안내"><a href="#/guide">팬 가이드</a><a href="#/status">자료 확인 상태</a><a href="#/review">검토 안내</a><a href="#/settings">설정</a><a href="https://isegye-idol.kr/auth/terms" target="_blank" rel="noopener noreferrer">이용약관 ↗</a><a href="https://isegye-idol.kr/auth/privacy" target="_blank" rel="noopener noreferrer">개인정보처리방침 ↗</a></nav></div></footer><nav class="mobile-nav" aria-label="모바일 메뉴">${[['home','오늘','spark'],['live','방송','video'],['schedule','일정','calendar'],['music','음악','music']].map(([id,label,glyph])=>`<a href="#/${id}" ${active===id?'aria-current="page"':''}>${icon(glyph)}${label}</a>`).join('')}<button data-action="more" aria-expanded="false" aria-controls="more-menu">${icon('menu')}더보기</button></nav><nav class="more-menu" id="more-menu" aria-label="더보기"><a href="#/members">멤버 소개</a><a href="#/history">활동 기록</a><a href="#/saved">저장함</a><a href="#/guide">팬 가이드</a><a href="#/settings">화면 설정</a><a href="#/review">검토 안내</a></nav>`;}

let liveRows=LIVE_CHANNELS.map(m=>liveEmpty(m,'unavailable')),liveBusy=false,liveAttempt=0;
function currentLive(){return liveRows.map(r=>liveEffective(r));}
function liveSummaryHtml(){const rows=currentLive(),on=rows.filter(r=>r.state==='live').length;return `<section class="panel live-summary" aria-label="실시간 방송 요약"><div class="section-head"><div><h2 class="live-title"><i class="dot"></i>LIVE <span>${on?on+'명 방송 중':liveBusy?'방송 상태 확인 중':'확인된 방송 '+on+'명'}</span></h2><p class="small muted" data-live-stamp>${liveAttempt?'조회 시도 '+stamp(new Date(liveAttempt).toISOString()):'아직 실시간 상태 확인 전'} · 30초마다 확인</p></div><a href="#/live" class="text-link">LIVE 전체 ${icon('arrow')}</a></div><div class="live-strip">${rows.map(r=>{const m=LIVE_CHANNELS.find(x=>x.id===r.id);return `<a class="live-mini" data-state="${r.state}" href="${r.state==='live'?liveWatchUrl(m):'#/member/'+r.id}" ${r.state==='live'?'target="_blank" rel="noopener noreferrer"':''}><img src="${D.assets.portraits[r.id]}" alt="" width="42" height="42"><span><strong>${m.name}</strong><small>${r.state==='live'?'● 방송 중':r.state==='offline'?'현재 방송 없음':'상태 확인 필요'}</small></span></a>`;}).join('')}</div></section>`;}
function homeView(p){
 const notice=D.notices.filter(r=>r.sourceId==='berriz-notice').sort(newest)[0],next=D.events.filter(r=>r.sourceId==='berriz-calendar'&&r.certainty==='confirmed'&&r.status!=='cancelled'&&(r.date>nowDay()||(r.date===nowDay()&&(!r.time||Date.parse(r.date+'T'+r.time+':00+09:00')>Date.now())))).sort((a,b)=>a.date.localeCompare(b.date))[0];
 const category=p.get('category')||'all';let recent=filtered(D.videos.filter(v=>v.category!=='replay'&&(category==='all'||v.category===category)),p).slice(0,6);
 const music=D.songs.filter(s=>s.type==='original').sort(newest),seen=new Set();const picks=music.filter(s=>{const k=s.albumId||s.id;if(seen.has(k))return false;seen.add(k);return true;}).slice(0,3);
 return heading('오늘의 이세돌','지금의 방송, 새로운 소식, 다시 보고 싶은 순간.','TODAY IN OUR ARCHIVE')+`<div id="live-region">${liveSummaryHtml()}</div><section class="panel brief" aria-label="공식 소식"><div><p class="eyebrow">공식 팬클럽 · 베리즈</p><h2>공식 소식</h2>${notice?`<a class="brief-row" href="${itemRoute(notice)}"><span class="small">최근 공지 <time>${dateText(notice.date)} · 게시</time></span><b>${esc(notice.title)} ↗</b></a>`:'<p class="brief-row muted">확인된 공지가 없습니다.</p>'}${next?`<a class="brief-row" href="${itemRoute(next)}"><span class="small">다음 일정 <time>${dateText(next.date)} · ${esc(next.time||'시간 미정')} KST</time></span><b>${esc(next.title)} →</b></a>`:'<p class="brief-row muted">저장 자료에서 다음 확정 일정을 확인하지 못했습니다.</p>'}<p class="small muted">검토용 저장 자료 · ${dateText(D.snapshotAt)} 확인</p></div><figure class="gallery" aria-label="이세계아이돌 단체 이미지" aria-live="off" data-index="0"><img id="group-photo" src="${D.gallery[0].src}" alt="${esc(D.gallery[0].alt)}" width="800" height="600"></figure></section><div class="catchup"><div><b>놓친 소식이 있나요?</b><p>날짜·멤버·콘텐츠를 함께 찾아보세요.</p></div><a class="text-link" href="${url('search',{from:kstDay(new Date(Date.now()-7*86400000).toISOString())})}">최근 자료 모아보기 ${icon('arrow')}</a></div><section class="section">${sectionHead('최근 콘텐츠','단체 공식·왁타버스·멤버 채널을 한곳에서.','영상 더 보기','#/live?tab=videos')}<div class="chips">${[['all','전체'],['group','단체 공식'],['member','멤버 채널']].map(([v,t])=>`<a class="chip ${category===v?'active':''}" href="${esc(patch({category:v}))}">${t}</a>`).join('')}</div><div class="filter-caption"></div>${memberChips(p)}<div class="section">${mediaGrid(recent)}</div><p class="data-note">기존 검증 목록을 통합한 검토본입니다. 날짜는 공개일·자료 기준일을 구분하며, 전체 과거 영상 목록은 아닙니다. <a class="accent" href="#/status">확인 시점 보기</a></p></section><section class="section">${sectionHead('음악으로 이어지는 순간','곡에서 음반으로, 음반에서 영상으로.','음악 전체','#/music')}${mediaGrid(picks)}</section><nav class="section grid two" aria-label="기록으로 이동"><a class="panel shortcut" href="#/schedule">${icon('calendar')}<div><h3>소식·일정</h3><p>공지 게시일과 실제 일정을 구분해서.</p></div>${icon('arrow')}</a><a class="panel shortcut" href="#/history">${icon('clock')}<div><h3>활동 기록</h3><p>음악·무대·콘텐츠를 하나의 이야기로.</p></div>${icon('arrow')}</a></nav>`;
}
function membersView(){return heading('여섯 멤버, 이어지는 기록','프로필에서 소식·영상·음악·활동으로 자연스럽게 이어가세요.','MEET THE SIX')+`<div class="grid members-grid">${D.members.map(m=>`<article class="panel member-card"><a href="#/member/${m.id}" class="member-art"><img src="${D.assets.portraits[m.id]}" alt="${m.name} 프로필" width="600" height="600" loading="lazy"></a><div class="member-copy"><p class="eyebrow tone-${m.id}">${m.en}</p><a href="#/member/${m.id}"><h2>${m.name}</h2></a><p>${esc(m.description)}</p><div class="small">${m.channels.length}개 채널 · 참여 음악 ${D.songs.filter(s=>s.members.includes(m.id)).length}개</div><div class="button-row"><a class="button" href="#/member/${m.id}">기록 모아보기 ${icon('arrow')}</a><button class="save" data-interest="${m.id}" aria-pressed="${prefs.interests.includes(m.id)}" aria-label="${m.name} 관심 멤버 ${prefs.interests.includes(m.id)?'해제':'추가'}">${icon('heart')}</button></div></div></article>`).join('')}</div><p class="data-note">관심 멤버는 여러 명 선택할 수 있습니다. 이 브라우저의 검토용 설정에만 저장되며 공식 계정과 동기화되지 않습니다.</p>`;}
function memberView(id,p){const m=persons.get(id);if(!m)return notFound();const tab=p.get('tab')||'intro',s=D.songs.filter(x=>x.members.includes(id)).sort(newest),v=D.videos.filter(x=>x.members.includes(id)).sort(newest),n=D.notices.filter(x=>x.members.includes(id)).sort(newest),h=D.history.filter(x=>x.members.includes(id)).sort(newest);
 let body='';if(tab==='intro'){body=`<div class="split"><div>${sectionHead('이 멤버를 만나는 세 가지 길')}<div class="list"><a class="panel shortcut" href="${url('member/'+id,{tab:'music'})}">${icon('music')}<div><h3>노래로 만나기</h3><p>확인된 참여 음악과 원본 영상</p></div>${icon('arrow')}</a><a class="panel shortcut" href="${url('member/'+id,{tab:'videos'})}">${icon('video')}<div><h3>영상으로 만나기</h3><p>채널의 용도를 확인하고 골라 보기</p></div>${icon('arrow')}</a><a class="panel shortcut" href="${url('member/'+id,{tab:'history'})}">${icon('clock')}<div><h3>활동 따라가기</h3><p>날짜별 주요 기록과 공개 출처</p></div>${icon('arrow')}</a></div></div><aside class="panel"><h3>공식 방송 채널</h3><p class="muted small">현재 방송 상태는 LIVE에서 확인하세요. 공지가 없다고 휴방으로 판단하지 않습니다.</p>${external(liveChannelUrl(LIVE_CHANNELS.find(x=>x.id===id)),'SOOP 채널 보기')}<a class="text-link" href="#/live">LIVE 상태 확인 ${icon('arrow')}</a></aside></div><section class="section">${sectionHead('채널별 역할','채널 이름보다 무엇을 볼 수 있는지 먼저 확인하세요.')}<div class="grid two">${m.channels.map(c=>`<div class="panel channel-row"><div>${badge(c.kind,'neutral')}<h3>${esc(c.name)}</h3><p>${esc(({본채널:'편집 영상과 주요 콘텐츠',음악:'음악·노래 관련 영상',다시보기:'공개된 전체 다시보기',서브:'별도 편집·짧은 콘텐츠'})[c.kind]||'채널 소개와 실제 목록에서 확인')}</p></div>${external(c.url,'채널 보기')}</div>`).join('')}</div></section>`;}
 if(tab==='news'){const pg=paginate(n,p);body=`<div class="result-bar"><p>확인된 공지 <strong>${n.length}</strong>건</p><a class="text-link" href="${url('schedule',{members:id})}">달력에서 보기 ${icon('arrow')}</a></div><div class="list">${pg.rows.map(rowCard).join('')}</div>${pg.html}`;}
 if(tab==='videos'){const pg=paginate(v,p);body=mediaGrid(pg.rows)+pg.html+`<p class="data-note">본인 채널 또는 자료에 표기된 참여 기준입니다. 다른 출연자·전체 방송일은 원문에서 확인합니다.</p>`;}
 if(tab==='music'){const pg=paginate(s,p);body=mediaGrid(pg.rows)+pg.html;}
 if(tab==='history'){body=h.length?`<div class="list">${h.map(rowCard).join('')}</div>`:empty('등록된 활동 기록이 없습니다','전체 활동의 완전한 목록은 아닙니다.');}
 return `<a class="text-link" href="#/members">${icon('back')}멤버 소개</a><section class="panel member-profile"><img src="${D.assets.portraits[id]}" alt="${m.name} 프로필" width="600" height="600"><div><p class="eyebrow tone-${id}">${m.en} · ISEGYE IDOL</p><h1>${m.name}</h1><p>${esc(m.description)}</p><dl class="facts">${[['팬덤',m.fanName],['상징색',m.colorName],['그룹 데뷔',dateText(m.debut)],['데뷔곡',m.debutTitle]].map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="button-row"><button class="button" data-interest="${id}" aria-pressed="${prefs.interests.includes(id)}">${icon('heart')}${prefs.interests.includes(id)?'관심 멤버 해제':'관심 멤버로 보기'}</button>${saveButton(memberItems.find(x=>x.id===id))}</div></div></section>${tabs([['intro','소개'],['news','소식',n.length],['videos','영상',v.length],['music','음악',s.length],['history','활동',h.length]],tab)}${body}<p class="data-note">프로필 확인 ${stamp(m.source?.checkedAt)} · ${external(m.source?.url,'프로필 자료 출처')}</p>`;
}

function scheduleView(p){
 const today=nowDay(),month=/^20\d{2}-(0[1-9]|1[0-2])$/.test(p.get('month')||'')?p.get('month'):today.slice(0,7),chosen=validDay(p.get('date'))&&p.get('date').startsWith(month)?p.get('date'):month===today.slice(0,7)?today:month+'-01';
 const view=p.get('view')||((innerWidth<=640)?'list':'calendar'),source=p.get('source')||'all',kind=p.get('kind')||'all';
 let rows=filtered([...D.notices,...D.events],p).filter(r=>r.date.startsWith(month));
 if(source==='berriz')rows=rows.filter(r=>r.sourceId?.startsWith('berriz'));if(source==='cafe')rows=rows.filter(r=>r.sourceId?.startsWith('cafe'));if(source==='fan')rows=[];
 if(kind!=='all')rows=rows.filter(r=>r.kind===kind);
 rows.sort((a,b)=>a.date.localeCompare(b.date)||(a.kind==='event'?-1:1)-(b.kind==='event'?-1:1)||(a.time||'99:99').localeCompare(b.time||'99:99')||newest(a,b));
 const fan=source==='all'||source==='fan'?D.forecasts.filter(r=>r.date.startsWith(month)&&memberMatches(r,selected(p),p.get('match')||'any')):[];
 const listDay=day=>{const list=rows.filter(x=>x.date===day),fore=fan.filter(x=>x.date===day);return `${list.length?`<div class="list">${list.map(rowCard).join('')}</div>`:empty('확인된 일정·공지가 없습니다','활동이 없다는 뜻은 아닙니다. 수집 상태와 공식 원문을 함께 확인해 주세요.')} ${fore.length?`<section class="panel forecast"><h3>방송 참고 ${badge('팬 정리 · 미확정','warning')}</h3><p class="small muted">공식 방송 확정 정보가 아닙니다. 실제 상태는 LIVE에서 확인하세요.</p>${fore.map(r=>`<div class="forecast-row"><strong class="tone-${r.members[0]}">${esc(memberText(r.members))}</strong><span>${esc(r.title.replace(memberText(r.members)+' · ',''))}</span></div>`).join('')}${external(fore[0].sourceUrl,'팬 정리 원문')}</section>`:''}`;};
 const [y,m]=month.split('-').map(Number),changeMonth=n=>{const d=new Date(Date.UTC(y,m-1+n,1));return patch({month:d.toISOString().slice(0,7),date:null,page:null});};
 const controls=`<section class="panel filters" aria-label="소식 일정 필터"><div class="filter-row"><label>연월<input type="month" data-filter="month" aria-label="보고 싶은 연월" value="${month}" min="2021-08"></label><a class="button" href="${url('schedule',{view})}">오늘</a>${choose('종류','kind',[['all','모든 일정·공지'],['event','실제 일정'],['notice','공지 게시 기록']],kind)}${choose('출처','source',[['all','전체 출처'],['berriz','베리즈 공식'],['cafe','멤버·소속사 카페'],['fan','팬 참고']],source)}${choose('멤버 조건','match',[['any','선택 멤버 중 누구나'],['all','선택 멤버 모두']],p.get('match')||'any')}</div>${memberChips(p)}<form class="search-form" data-query-form><label class="sr-only" for="schedule-search">공지·일정 제목 검색</label><input id="schedule-search" type="search" name="q" value="${esc(p.get('q')||'')}" placeholder="이 달의 공지·일정 제목 검색" maxlength="180"><button type="submit">검색</button></form></section>`;
 let content='';
 if(view==='calendar')content=`<section class="panel calendar-panel"><div class="calendar-heading"><h2>${y}년 ${m}월</h2><div class="calendar-controls"><a class="button" href="${esc(changeMonth(-1))}" aria-label="이전 달">${icon('back')}</a><a class="button" href="${esc(changeMonth(1))}" aria-label="다음 달">${icon('arrow')}</a></div></div><div class="calendar-week" aria-hidden="true">${['일','월','화','수','목','금','토'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${calendarDays(month).map(d=>{if(!d)return '<span></span>';const rs=rows.filter(x=>x.date===d),ns=rs.filter(x=>x.kind==='notice').length;return `<a class="day ${d===chosen?'selected':''} ${d===today?'today':''}" href="${esc(patch({date:d,view:'calendar'}))}" aria-label="${d} 일정 ${rs.length-ns}건 공지 ${ns}건" ${d===chosen?'aria-current="date"':''}><span class="day-number">${+d.slice(-2)}${d===today?'<small>오늘</small>':''}</span>${rs.slice(0,4).map(r=>`<span class="day-chip ${r.kind} ${r.members.length===1?'tone-'+r.members[0]:''}">${esc(r.title.replace(/^\[[^\]]+\]\s*/,''))}</span>`).join('')}<span class="day-more">${rs.length?`${rs.length-ns?'일정 '+(rs.length-ns)+' ':''}${ns?'공지 '+ns:''}`:''}</span></a>`;}).join('')}</div></section><section class="agenda" id="selected-day">${sectionHead(dateText(chosen),'선택한 날짜 · 공지 게시일과 실제 일정은 구분합니다.')}${listDay(chosen)}</section>`;
 else {const days=[...new Set([...rows.map(r=>r.date),...fan.map(r=>r.date)])].sort().reverse();content=`<div class="calendar-heading"><h2>${y}년 ${m}월</h2><div class="calendar-controls"><a class="button" href="${esc(changeMonth(-1))}" aria-label="이전 달">${icon('back')}</a><a class="button" href="${esc(changeMonth(1))}" aria-label="다음 달">${icon('arrow')}</a></div></div>${days.length?days.map(d=>`<section class="day-group"><h3>${dateText(d)} ${d===today?badge('오늘'):''}</h3>${listDay(d)}</section>`).join(''):empty('이 달에 확인된 항목이 없습니다','필터를 바꾸거나 다른 달을 선택해 보세요.','#/schedule','오늘로 돌아가기')}`;}
 return heading('소식·일정','언제 올린 공지인지, 언제 열리는 일정인지 구분해서.','CALENDAR & NEWS')+controls+`<div class="result-bar"><p>이 달 일정 <strong>${rows.filter(r=>r.kind==='event').length}</strong>건 · 공지 <strong>${rows.filter(r=>r.kind==='notice').length}</strong>건</p><a class="text-link" href="${url('schedule',{month,view})}">필터 초기화</a></div>${tabs([['calendar','월간 달력'],['list','날짜순 목록']],view,'view')}<div class="legend">${D.members.map(x=>`<span class="tone-${x.id}"><i class="dot"></i> ${x.name}</span>`).join('')}</div>${content}<div class="notice-box">검토용 저장 자료 기준입니다. 공지 원문 변경·삭제와 현재 수집 상태는 실시간으로 반영되지 않습니다. <a class="accent" href="#/status">출처별 확인 시점 보기 →</a></div>`;
}
function sourceBox(r){const links=r.sourceLinks||[{title:sourceLabel(r),url:r.url}];return `<aside class="panel detail-aside"><h3>자료 기준과 출처</h3><p>원문 전체·현재 공개 상태·변경 사항은 제공처에서 확인하세요.</p><div class="source-list">${links.map(s=>external(s.url,s.title)).join('')}</div><p>자료 확인 ${r.checkedAt?stamp(r.checkedAt):'기준 자료 참조'}</p><div class="button-row"><button class="button" data-copy>${icon('external')}이 기록 주소 복사</button></div></aside>`;}
function noticeView(id){const r=notices.get(id);if(!r)return notFound();const related=D.notices.filter(n=>n.id!==id&&memberMatches(n,r.members)).sort(newest).slice(0,3),linked=D.events.filter(e=>e.sourceUrl===r.url);
 return `<a class="text-link" href="${url('schedule',{month:r.date.slice(0,7),date:r.date})}">${icon('back')}소식·일정</a><div class="split"><article><div class="badges">${badge('공지 게시 기록')}${badge(sourceLabel(r),'neutral')}</div><header class="detail-title"><h1>${esc(r.title)}</h1></header><div class="detail-meta"><span>${esc(memberText(r.members))}</span><time>${stamp(r.publishedAt)}</time></div><p class="detail-copy">${esc(r.summary)}</p><div class="notice-box"><strong>이 날짜는 공지가 게시된 날짜입니다.</strong><br>제목만으로 실제 방송 시각이나 개최 여부를 확정하지 않습니다. 원문을 우선 확인해 주세요.</div><div class="button-row">${external(r.url,'공식 원문 보기','button primary')}${saveButton(r)}</div><section class="section">${sectionHead('연결된 일정')}${linked.length?`<div class="list">${linked.map(rowCard).join('')}</div>`:empty('확정된 연결 일정이 없습니다','공지의 게시 시각을 방송·행사 시각으로 대신 등록하지 않았습니다.')}</section><section class="section">${sectionHead('변경 이력')}<div class="notice-box">공지의 수정 전·후 본문 이력은 아직 수집하지 않습니다. 현재 원문에서 최신 안내를 확인하세요. 변경 이력 기능은 다음 운영 연동 검토 항목입니다.</div></section><section class="section">${sectionHead('관련 멤버의 최근 공지')}<div class="list">${related.map(rowCard).join('')}</div></section></article>${sourceBox(r)}</div>`;
}
function eventView(id){const r=events.get(id);if(!r)return notFound();const approved=r.certainty==='confirmed'&&r.status!=='cancelled';
 const nearby=D.notices.filter(n=>n.sourceId==='berriz-notice'&&normalized(n.title).includes('acrossdimensions')&&normalized(r.title).includes('acrossdimensions'));
 return `<a class="text-link" href="${url('schedule',{month:r.date.slice(0,7),date:r.date})}">${icon('back')}소식·일정</a><div class="split"><article><div class="badges">${badge(approved?'확정 일정':r.status==='cancelled'?'취소 일정':'미확정 일정',approved?'good':'warning')}${badge(sourceLabel(r),'neutral')}</div><header class="detail-title"><h1>${esc(r.title)}</h1></header><div class="detail-meta">${esc(memberText(r.members))}</div><section class="panel section"><dl class="facts"><div><dt>일정 날짜</dt><dd>${dateText(r.date)}</dd></div><div><dt>한국시간</dt><dd>${esc(r.time||'시각 미정')}${r.time?' KST':''}</dd></div><div><dt>종료</dt><dd>${r.endAt?stamp(r.endAt):'명시되지 않음'}</dd></div></dl><p class="detail-copy">${esc(r.summary)}</p><div class="button-row">${external(r.url,'공식 일정 원문','button primary')}${saveButton(r)}<button class="button" data-ics="${esc(r.id)}" ${approved?'':'disabled'}>${icon('download')}캘린더 파일 저장</button></div><p class="data-note">.ics 파일을 내려받는 방식입니다. 자동 구독·변경 동기화는 아니므로 일정 변경·취소는 공식 원문에서 다시 확인하세요.</p></section><section class="section">${sectionHead('함께 확인할 공지')}${nearby.length?`<div class="list">${nearby.map(rowCard).join('')}</div>`:empty('연결된 추가 공지가 없습니다','자동으로 비슷한 제목을 확정된 관련 자료로 묶지 않습니다.')}</section><section class="panel section"><h3>이 일정 알림</h3><p class="muted">알림 채널·발송 서버는 아직 연결하지 않았습니다. 검토 페이지에서는 알림 설정 화면만 살펴볼 수 있습니다.</p><a class="text-link" href="#/settings">알림 설계 보기 ${icon('arrow')}</a></section></article>${sourceBox(r)}</div>`;
}

function albumCard(a){return `<article class="content-card"><a href="#/album/${a.id}"><div class="album-art">${icon('music')}<strong>${esc(a.title)}</strong><small>목록용 그래픽 · 공식 커버 아님</small></div></a><div class="card-body"><div class="badges">${badge('음반')}${badge(a.format,'neutral')}</div><a href="#/album/${a.id}"><h3>${esc(a.title)}</h3></a><p>${esc(memberText(a.members))}</p><div class="card-bottom"><span>${dateText(a.date)}</span>${saveButton(a)}</div></div></article>`;}
function musicView(p){const tab=p.get('tab')||'songs',type=p.get('type')||'all';const yearOptions=[['all','전체 연도'],...[...new Set(D.songs.map(s=>s.date.slice(0,4)))].sort().reverse().map(y=>[y,y+'년'])];
 let items=filtered(tab==='albums'?D.albums:tab==='videos'?D.videos.filter(v=>v.category==='group'):D.songs,p);if(tab==='songs'&&type!=='all')items=items.filter(s=>s.type===type);if(p.get('sort')==='old')items.reverse();if(p.get('sort')==='title')items.sort((a,b)=>a.title.localeCompare(b.title,'ko'));const pg=paginate(items,p);
 const pending=D.events.find(e=>e.type==='release'&&e.date>=nowDay());
 return heading('한 곡에서 시작되는 이야기','오리지널·커버부터 음반과 공식 무대까지, 같은 기록으로 이어갑니다.','MUSIC LIBRARY')+tabs([['songs','곡',D.songs.length],['albums','음반',D.albums.length],['videos','공식 음악 영상']],tab)+`<section class="panel filters"><form class="search-form" data-query-form><label class="sr-only" for="music-q">음악 검색</label><input type="search" id="music-q" name="q" value="${esc(p.get('q')||'')}" placeholder="곡·앨범·멤버·한글 별칭 검색" maxlength="180"><button type="submit">검색</button></form>${memberChips(p)}<div class="filter-row">${tab==='songs'?choose('곡 종류','type',[['all','모든 곡'],['original','오리지널'],['cover','커버'],['remake','리메이크']],type):''}${choose('연도','year',yearOptions,p.get('year')||'all')}${choose('정렬','sort',[['new','발매·공개 최신순'],['old','오래된순'],['title','제목순']],p.get('sort')||'new')}${choose('멤버 조건','match',[['any','선택 멤버 중 누구나'],['all','선택 멤버 모두']],p.get('match')||'any')}</div></section>${pending&&tab==='albums'?`<div class="notice-box">${badge('발매 예정','warning')} <a class="accent" href="${itemRoute(pending)}">${esc(pending.title)}</a><br>${dateText(pending.date)} · 공개된 메들리와 정식 발매일을 구분합니다.</div>`:''}<div class="result-bar"><p><strong>${items.length}</strong>개 ${tab==='albums'?'음반':'기록'}</p><a class="text-link" href="${url('music',{tab})}">필터 초기화</a></div>${tab==='albums'?(pg.rows.length?`<div class="grid">${pg.rows.map(albumCard).join('')}</div>`:empty('조건에 맞는 음반이 없습니다','검색 조건을 바꿔 보세요.')):mediaGrid(pg.rows)}${pg.html}<details class="notice-box"><summary>목록 기준과 출처</summary><p>등록 음악 ${D.songs.length}개를 바탕으로 한 검토용 목록입니다. 발매일·영상 공개일을 구분하고 공식 영상·팬 백업을 별도 표시합니다. 모든 개인 방송 선곡이나 전체 과거 음악을 빠짐없이 수록한 목록은 아닙니다.</p></details>`;
}
function songView(id){const s=songs.get(id);if(!s)return notFound();const album=albums.get(s.albumId),related=D.history.filter(h=>h.relatedSong===id),relatedVideos=D.videos.filter(v=>v.relatedSong===id||v.id===s.videoId),sourceKind=s.videoSource?.kind;
 return `<a class="text-link" href="#/music">${icon('back')}음악 목록</a><div class="split"><article><div class="badges">${badge(songTypes[s.type]||s.type)}${badge(s.members.length===6?'단체':s.members.length===1?'솔로':'유닛','neutral')}${sourceKind==='fan_backup'?badge('현재 연결: 팬 백업','warning'):''}</div><header class="detail-title"><h1>${esc(s.title)}</h1></header><p class="detail-meta">${esc(memberText(s.members))}</p><div class="section grid two"><div class="detail-cover">${thumb(s)}</div><div><dl class="facts"><div><dt>${esc(s.dateKind)}</dt><dd>${dateText(s.date)}</dd></div><div><dt>공개 형식</dt><dd>${esc(s.format)}</dd></div></dl>${album?`<p class="data-note">수록 음반 <a class="accent" href="#/album/${album.id}">${esc(album.title)} →</a></p>`:''}<div class="button-row">${external(s.url||(s.videoId?'https://www.youtube.com/watch?v='+s.videoId:''),sourceKind==='fan_backup'?'팬 백업 영상 보기':'연결된 영상 보기','button primary')}${saveButton(s)}</div>${s.originalReference?external(s.originalReference,'원곡·관련 문서'):''}</div></div><section class="section">${sectionHead('공개 형태와 원본 연결','공식·팬 백업을 구분하고 같은 곡의 자료를 함께 확인합니다.')}<div class="panel"><div class="badges">${badge(({official_mv:'공식 MV',official_audio:'공식 음원',official_video:'공식 영상',fan_backup:'팬 백업',unavailable:'현재 연결 없음'})[sourceKind]||'출처 확인','neutral')}</div><h3>${esc(s.videoSource?.channel||'자료 제공처 확인')}</h3><p class="muted small">${esc(s.videoSource?.note||'전체 재생 및 현재 공개 여부는 원본에서 확인하세요.')}</p>${s.originalVideoId&&s.originalVideoId!==s.videoId?external('https://www.youtube.com/watch?v='+s.originalVideoId,'원본 기록 · 현재 공개 여부 재확인'):''}</div>${relatedVideos.length?`<div class="section">${mediaGrid(relatedVideos)}</div>`:''}</section>${album?`<section class="section">${sectionHead('같은 음반으로 이어가기')}<div class="list">${album.songIds.filter(x=>x!==id).map(x=>songs.get(x)).filter(Boolean).map(rowCard).join('')||`<a class="panel shortcut" href="#/album/${album.id}">${icon('music')}<div><h3>${esc(album.title)}</h3><p>확인된 수록곡과 공개 자료 보기</p></div>${icon('arrow')}</a>`}</div></section>`:''}<section class="section">${sectionHead('관련 활동 기록')}${related.length?`<div class="list">${related.map(rowCard).join('')}</div>`:empty('검증된 연결 기록이 아직 없습니다','추가 영상·무대·크레딧은 출처를 확인한 뒤 연결합니다.')}</section><div class="notice-box">노래 방송의 선곡표·타임스탬프, 상세 제작 크레딧과 가사·음원은 이 검토본에 임의로 추가하지 않았습니다.</div></article>${sourceBox(s)}</div>`;
}
function albumView(id){const a=albums.get(id);if(!a)return notFound();const rs=a.songIds.map(x=>songs.get(x)).filter(Boolean),tracks=a.tracks.length?a.tracks:rs.map(s=>s.title);return `<a class="text-link" href="#/music?tab=albums">${icon('back')}음반 목록</a><div class="split"><article><div class="detail-cover"><div class="album-art">${icon('music')}<strong>${esc(a.title)}</strong><small>목록용 그래픽 · 공식 음반 커버 아님</small></div></div>${badge('음반 상세')}<header class="detail-title"><h1>${esc(a.title)}</h1></header><p class="detail-meta">${esc(memberText(a.members))} · ${dateText(a.date)}</p><div class="button-row">${saveButton(a)}</div><section class="section">${sectionHead('확인된 수록곡','곡의 세부 기록이 있는 경우 해당 곡으로 바로 연결합니다.')}<div class="panel">${tracks.map((t,i)=>{const s=rs.find(s=>normalized(s.title)===normalized(t));return `<div class="track-row"><span class="track-index">${String(i+1).padStart(2,'0')}</span><span class="track-name">${s?`<a href="#/song/${s.id}">${esc(t)} →</a>`:esc(t)}</span>${s?saveButton(s):badge('트랙명 확인','neutral')}</div>`;}).join('')}</div></section><section class="section">${sectionHead('곡별 영상·자료')}${mediaGrid(rs)}</section><p class="data-note">공식 발매 순서와 공개된 트랙 표기를 기준으로 합니다. 정보가 없는 트랙의 영상이나 크레딧은 추정하지 않습니다.</p></article>${sourceBox(a)}</div>`;}

function liveCardsHtml(p){const status=p.get('status')||'all',ids=selected(p),rows=liveSorted(currentLive()).filter(r=>(status==='all'||r.state===status)&&(!ids.length||ids.includes(r.id)));return rows.length?`<div class="grid">${rows.map(r=>{const m=LIVE_CHANNELS.find(x=>x.id===r.id),note=D.notices.filter(n=>n.members.length===1&&n.members[0]===r.id).sort(newest)[0];return `<article class="content-card live-card" data-state="${r.state}"><div class="member-art"><img src="${D.assets.portraits[r.id]}" alt="${m.name}" width="150" height="150"></div><div class="live-info"><h3>${m.name}${badge(r.state==='live'?'방송 중':r.state==='offline'?'현재 방송 없음':'확인 필요',r.state==='live'?'good':'neutral')}</h3><p>${esc(r.state==='live'?r.title:r.state==='offline'?'조회 시점에 진행 중인 방송이 확인되지 않았습니다. 오늘 휴방이라는 뜻은 아닙니다.':'현재 방송 여부를 확인하지 못했습니다. 공식 채널에서 확인하세요.')}</p>${external(r.state==='live'?liveWatchUrl(m):liveChannelUrl(m),r.state==='live'?'방송 보러 가기':'공식 채널 보기','button primary')}${note?`<div class="notice-box"><small>저장된 최근 공지 · ${dateText(note.date)}</small><br><a href="${itemRoute(note)}">${esc(note.title)}</a></div>`:''}</div></article>`;}).join('')}</div>`:empty('확인된 방송이 없습니다','조회 실패나 미확인 상태는 방송 종료를 뜻하지 않습니다.','#/live','전체 멤버 보기');}
function liveView(p){const tab=p.get('tab')||'now';let body='';
 if(tab==='now')body=`<div class="panel filters"><div class="filter-row">${choose('방송 상태','status',[['all','전체 멤버'],['live','방송 중만'],['unknown','상태 확인 필요']],p.get('status')||'all')}<button class="button" data-action="refresh-live" ${liveBusy?'disabled':''}>${liveBusy?'확인 중…':'방송 상태 확인'}</button><span class="small muted">원본 조회 30초 간격 · 실패 시 확인 필요</span></div>${memberChips(p)}</div><div id="live-cards">${liveCardsHtml(p)}</div><p class="data-note">실시간 API 조회와 공지 기록은 별개입니다. 실제 방송 시각을 예측하거나 공지 미발견을 휴방으로 표시하지 않습니다.</p>`;
 if(tab==='videos'||tab==='replay'){const category=p.get('category')||'all';let rs=filtered(D.videos.filter(v=>tab==='replay'?v.category==='replay':v.category!=='replay'),p);if(category!=='all')rs=rs.filter(v=>v.category===category);const pg=paginate(rs,p);body=`<section class="panel filters"><form class="search-form" data-query-form><label class="sr-only" for="video-q">영상 제목 검색</label><input id="video-q" type="search" name="q" value="${esc(p.get('q')||'')}" placeholder="영상 제목·콘텐츠·멤버 검색" maxlength="180"><button type="submit">검색</button></form>${memberChips(p)}<div class="filter-row">${tab==='videos'?choose('채널 범위','category',[['all','전체'],['group','단체 공식·왁타버스'],['member','멤버 채널']],category):''}${choose('멤버 조건','match',[['any','선택 멤버 중 누구나'],['all','자료에 선택 멤버 모두 표기']],p.get('match')||'any')}<a class="text-link" href="#/settings">제목·썸네일 가림 설정</a></div></section>${tab==='replay'?'<div class="notice-box"><strong>공개 다시보기 채널에서 확인한 영상입니다.</strong> 표시 날짜는 업로드일입니다. 방송일·전체 출연진·회차·타임스탬프는 별도 검증 전이며, 제목에서 임의로 추정하지 않습니다.</div>':''}<div class="result-bar"><p><strong>${rs.length}</strong>개 공개 영상</p><a class="text-link" href="${url('live',{tab})}">필터 초기화</a></div>${mediaGrid(pg.rows)}${pg.html}`;}
 if(tab==='series')body=`<div class="grid two">${D.series.map(seriesCard).join('')}</div><section class="section panel"><h2>같은 합방, 다른 시점</h2><p class="muted">여러 멤버의 원본을 같은 방송으로 연결하는 화면 구성입니다. 방송 ID·참여자·원본 시점이 검증된 자료가 아직 없어 임의의 합방 묶음은 만들지 않았습니다.</p><div class="button-row">${D.members.map(m=>external(m.channels.find(c=>c.kind==='다시보기')?.url,m.name+' 다시보기','button')).join('')}</div><p class="data-note">합방별 시점 전환·회차·선곡표는 검증된 연결 데이터가 준비된 뒤 제공됩니다. 현재 버튼은 공식 채널로 이동합니다.</p></section>`;
 return heading('지금 보고, 놓친 순간도 찾고','실제 방송 상태와 공지, 다시보기와 주요 콘텐츠를 구분해서.','LIVE & BROADCAST')+tabs([['now','방송 중'],['videos','최근 영상'],['replay','다시보기'],['series','시리즈·합방']],tab)+body;
}
function videoView(id){const v=videos.get(id);if(!v)return notFound();const same=D.series.filter(s=>s.videoIds?.includes(id)),seq=same[0],index=seq?.videoIds.indexOf(id),s=songs.get(v.relatedSong)||D.songs.find(s=>s.videoId===id);
 return `<a class="text-link" href="${url('live',{tab:v.category==='replay'?'replay':'videos'})}">${icon('back')}방송·영상 목록</a><div class="split"><article><div class="detail-cover">${thumb(v)}</div><div class="badges">${badge(v.format||'영상')}${badge(v.channelName,'neutral')}</div><header class="detail-title"><h1>${esc(v.title)}</h1></header><div class="detail-meta">${dateText(v.date)} · ${esc(v.dateLabel||'영상 공개일')} · ${esc(memberText(v.members))}</div><p class="detail-copy">${esc(v.summary)}</p><div class="button-row">${external(v.url,'YouTube 원본에서 보기','button primary')}${saveButton(v)}<button class="button" data-watched="${esc(v.key)}" aria-pressed="${prefs.watched.includes(v.key)}">${icon('check')}${prefs.watched.includes(v.key)?'시청 표시 해제':'직접 시청 완료 표시'}</button></div><p class="data-note">링크를 열었다고 시청 완료로 처리하지 않습니다. 시청 표시는 이 브라우저에만 저장됩니다.</p><section class="section panel"><h3>방송일·참여 멤버·타임스탬프</h3><p class="muted">${v.memberBasis==='channel_owner'?'현재 멤버 표시는 채널 운영자 기준입니다. 전체 참여자나 실제 방송일을 뜻하지 않습니다.':'자료에 명시된 크레딧 기준으로 연결했습니다.'} 확인되지 않은 방송일·구간·발언 요약은 제공하지 않습니다.</p></section>${s?`<section class="section">${sectionHead('연결된 곡')}<div class="list">${rowCard(s)}</div></section>`:''}${seq?`<section class="section">${sectionHead('같은 기획에서 이어보기')}<div class="grid two">${same.map(seriesCard).join('')}</div><div class="button-row">${index>0?`<a class="button" href="#/video/${seq.videoIds[index-1]}">이전 연결 영상</a>`:''}${index<seq.videoIds.length-1?`<a class="button" href="#/video/${seq.videoIds[index+1]}">다음 연결 영상</a>`:''}</div></section>`:''}</article>${sourceBox(v)}</div>`;
}
function seriesView(id){const s=D.series.find(s=>s.id===id);if(!s)return notFound();const vs=(s.videoIds||[]).map(id=>videos.get(id)).filter(Boolean),ss=(s.songIds||[]).map(id=>songs.get(id)).filter(Boolean);return `<a class="text-link" href="#/live?tab=series">${icon('back')}시리즈·합방</a>${heading(s.title,s.description,s.subtitle)}<div class="notice-box">${badge(s.status)} ${s.basis==='editorial'?'운영자가 검토용으로 선정한 입문 경로입니다. 공식 추천·인기순·전체 기록이 아닙니다.':'같은 행사와 관련된 확인된 공식 영상입니다. 한 방송의 멀티시점이나 전체 공연 세트리스트를 뜻하지 않습니다.'}</div>${mediaGrid([...vs,...ss])}<section class="section">${sectionHead('맥락을 더 살펴보기')}<div class="list">${D.history.filter(h=>h.title.includes('이세계페스티벌')).slice(-3).map(rowCard).join('')}</div></section>`;}
function historyView(p){const type=p.get('type')||'all';let rows=filtered(D.history,p);if(type!=='all')rows=rows.filter(r=>r.type===type);const years=[...new Set(D.history.map(r=>r.date.slice(0,4)))].sort().reverse();return heading('기록과 기록 사이의 이야기','일상 공지는 소식·일정에서, 주요 활동의 흐름은 이곳에서.','OUR TIMELINE')+`<section class="panel filters"><div class="filter-row">${choose('연도','year',[['all','전체 연도'],...years.map(y=>[y,y+'년'])],p.get('year')||'all')}${choose('활동 종류','type',[['all','모든 활동'],...Object.entries(historyTypes)],type)}<form class="search-form" data-query-form><label class="sr-only" for="history-q">활동 검색</label><input id="history-q" type="search" name="q" value="${esc(p.get('q')||'')}" placeholder="행사·작품·기록 이름 검색"><button type="submit">검색</button></form></div>${memberChips(p)}</section><div class="result-bar"><p><strong>${rows.length}</strong>개 주요 기록</p><a class="text-link" href="#/history">필터 초기화</a></div><div class="timeline">${rows.length?years.filter(y=>rows.some(r=>r.date.startsWith(y))).map(y=>`<h2 class="timeline-year">${y}</h2>${rows.filter(r=>r.date.startsWith(y)).map(rowCard).join('')}`).join(''):empty('조건에 맞는 기록이 없습니다','자료가 없다고 활동이 없었다는 뜻은 아닙니다.')}</div><div class="notice-box">${dateText(D.scope.historyCheckedAt)}에 확인한 주요 활동을 보여주는 검토 스냅샷입니다. 월간 활동 수집·이후 추가된 기록은 이 파일에서 실시간 갱신하지 않습니다.</div>`;}
function historyDetail(id){const h=histories.get(id);if(!h)return notFound();const song=songs.get(h.relatedSong);return `<a class="text-link" href="#/history">${icon('back')}활동 기록</a><div class="split"><article>${badge(historyTypes[h.type]||h.type)}<header class="detail-title"><h1>${esc(h.title)}</h1></header><div class="detail-meta">${dateText(h.date)} · ${esc(memberText(h.members))}</div><p class="detail-copy">${esc(h.summary)}</p>${h.note&&h.note!==h.summary?`<p class="muted">${esc(h.note)}</p>`:''}<div class="button-row">${saveButton(h)}<a class="button" href="${url('schedule',{month:h.date.slice(0,7),date:h.date})}">그 날짜의 공지 보기</a></div>${song?`<section class="section">${sectionHead('이 기록의 음악')}<div class="list">${rowCard(song)}</div></section>`:''}<section class="section">${sectionHead('관련 멤버')}<div class="chips">${h.members.map(id=>`<a class="chip tone-${id}" href="#/member/${id}">${names[id]} →</a>`).join('')}</div></section><section class="panel section"><h3>공연 준비·세트리스트·후속 영상</h3><p class="muted">정확히 확인된 관련 자료만 이 기록에 연결합니다. 현재 근거가 없는 공연 세트리스트나 후기 방송은 임의로 구성하지 않았습니다.</p>${h.title.includes('이세계페스티벌')?`<a class="text-link" href="#/series/festival-2025">2025 공식 무대 모아보기 ${icon('arrow')}</a>`:''}</section></article>${sourceBox(h)}</div>`;}

function searchView(p){const q=p.get('q')||'',kind=p.get('kind')||'all';let result=filtered(allItems,p);const counts=Object.fromEntries(Object.keys(types).map(k=>[k,result.filter(r=>r.kind===k).length]));if(kind!=='all')result=result.filter(r=>r.kind===kind);const pg=paginate(result,p);const parsed=queryParts(q,new Date().getFullYear());
 return heading('궁금한 순간을 찾아보세요','멤버·곡·공지·일정·영상·활동 기록을 한 번에 찾습니다.','SEARCH THE ARCHIVE')+`<section class="panel filters large-search"><form class="search-form" id="global-search"><label class="sr-only" for="global-query">통합 검색어</label><input id="global-query" name="q" type="search" maxlength="180" value="${esc(q)}" placeholder="예: 릴파 11월 3일, 리와인드, ㅇㅇㄴ" autocomplete="off"><button type="submit" class="button primary">검색</button></form><p class="small muted">제목·멤버·날짜·기존 별칭과 한글 초성으로 찾습니다. AI가 없는 기록을 만들어 답하지 않습니다.</p><div class="filter-row"><label>시작 날짜<input type="date" data-filter="from" aria-label="검색 시작 날짜" value="${validDay(p.get('from'))?p.get('from'):''}"></label><label>종료 날짜<input type="date" data-filter="to" aria-label="검색 종료 날짜" value="${validDay(p.get('to'))?p.get('to'):''}"></label>${choose('멤버 조건','match',[['any','선택 멤버 중 누구나'],['all','선택 멤버 모두']],p.get('match')||'any')}</div>${memberChips(p)}</section>${parsed.dates.length?`<div class="notice-box">입력에서 해석한 날짜: <strong>${parsed.dates.map(dateText).join(', ')}</strong> · 자료별 날짜 의미는 결과에 구분 표시합니다.</div>`:''}${tabs([['all','전체',Object.values(counts).reduce((a,b)=>a+b,0)],...Object.entries(types).map(([k,v])=>[k,v,counts[k]])],kind,'kind')}<div class="result-bar"><p>${q?'“'+esc(q)+'” · ':''}<strong>${result.length.toLocaleString('ko-KR')}</strong>개 검색 결과</p><a class="text-link" href="#/search">검색 초기화</a></div>${result.length?`<div class="list">${pg.rows.map(rowCard).join('')}</div>${pg.html}`:empty('조건에 맞는 기록이 없습니다','다른 표기나 날짜 범위로 다시 찾아보세요. 아직 수록하지 않은 자료일 수 있습니다.','#/search','전체 기록 둘러보기')}`;
}
function savedView(p){const kind=p.get('kind')||'all';let rs=prefs.favorites.map(k=>registry.get(k)).filter(Boolean);const total=rs.length;if(kind!=='all')rs=rs.filter(r=>r.kind===kind);const pg=paginate(rs,p);return heading('다시 보고 싶은 순간','메뉴가 달라도 한곳에. 이 브라우저에만 저장되는 나만의 기록장.','YOUR COLLECTION')+`<div class="notice-box">${storageAvailable?'검토용 브라우저 저장소를 사용합니다.':'브라우저 영구 저장을 사용할 수 없어 이 탭에서만 유지됩니다.'} 로그인 계정과 동기화되지 않으며 운영 사이트의 기존 저장함은 변경하지 않습니다.</div>${tabs([['all','전체',total],['member','멤버'],['notice','공지'],['event','일정'],['song','음악'],['video','나중에 볼 영상'],['history','활동'],['album','음반']],kind,'kind')}<div class="result-bar"><p>저장한 기록 <strong>${rs.length}</strong>개</p><button class="button" data-action="export-saved">${icon('download')}저장 목록 백업</button></div>${rs.length?`<div class="list">${pg.rows.map(rowCard).join('')}</div>${pg.html}`:empty('이 분류에 저장한 기록이 없습니다','각 자료의 하트 버튼으로 보관해 보세요. 모든 메뉴의 자료를 같은 저장함에서 찾을 수 있습니다.','#/music','음악 둘러보기')}<section class="panel section"><h3>관심 멤버</h3><p class="muted small">관심 멤버는 기록 저장과 별개입니다. 여러 명을 선택할 수 있습니다.</p><div class="button-row">${D.members.map(m=>`<button class="chip tone-${m.id}" data-interest="${m.id}" aria-pressed="${prefs.interests.includes(m.id)}"><i class="dot"></i>${m.name}</button>`).join('')}</div>${prefs.interests.length?`<a class="text-link" href="${url('search',{members:prefs.interests.join(',')})}">관심 멤버 자료 모아보기 ${icon('arrow')}</a>`:''}</section>`;}
function guideView(p){const tab=p.get('tab')||'start';let body='';if(tab==='start')body=`<div class="grid">${[['music','노래로 알아보기','공식 음악과 커버, 음반과 영상을 연결해서.','#/series/music-beginning'],['users','멤버별로 알아보기','프로필과 채널의 용도를 먼저 살펴보세요.','#/members'],['video','단체 콘텐츠로 알아보기','단체 공식 채널·왁타버스 영상으로 이어집니다.','#/live?tab=videos&category=group']].map(([g,t,d,h])=>`<a class="series-card" href="${h}"><span class="series-icon">${icon(g)}</span><h2>${t}</h2><p>${d}</p><span class="text-link">둘러보기 ${icon('arrow')}</span></a>`).join('')}</div><section class="panel section"><h2>오랜만에 돌아왔나요?</h2><p class="muted">전체를 다시 배울 필요 없이, 관심 멤버와 기간으로 등록 자료를 찾아보세요.</p><div class="button-row"><a class="button" href="${url('search',{from:kstDay(new Date(Date.now()-30*86400000).toISOString())})}">최근 한 달 자료</a>${previousVisit?`<a class="button" href="${url('search',{from:kstDay(previousVisit)})}">이전 방문일 이후 자료</a>`:''}</div><p class="data-note">자료가 추가된 시각이 아니라 기록의 날짜로 필터링합니다. 과거 날짜로 뒤늦게 등록된 항목까지 잡아내는 ‘새로 추가된 자료’ 기능은 운영 연동 전입니다.</p></section>`;
 if(tab==='terms')body=`<div class="prose"><h2>자료를 읽을 때 알아두면 좋은 표현</h2><div class="panel"><h3>LIVE와 휴방</h3><p>LIVE는 조회 시점의 방송 상태입니다. ‘방송 없음’이나 ‘확인 필요’는 당일 휴방 안내가 아닙니다.</p><h3>다시보기와 편집본</h3><p>같은 활동에서 나온 영상이라도 전체 방송, 편집 영상, 짧은 클립은 서로 다른 자료입니다. 원본 공개일과 실제 방송일을 구분합니다.</p><h3>팬 정리·뱅온정보</h3><p>팬이 정리한 참고 자료입니다. 멤버의 공식 안내나 실제 방송 상태와 같다고 보지 않습니다.</p><h3>확인 시각과 게시일</h3><p>자료를 확인한 날과 원문이 올라온 날은 다를 수 있습니다. 행사 날짜가 따로 있다면 별도 일정으로 연결합니다.</p></div><p class="data-note">운영자가 작성한 이용 설명이며 멤버의 발언이나 공식 용어 정의가 아닙니다.</p></div>`;
 if(tab==='participate')body=`<div class="grid two"><section class="panel"><h2>공식 안내를 먼저 확인하세요</h2><p class="muted">공연·팬 활동·창작의 기준은 최신 공식 원문을 우선 확인합니다.</p><div class="source-list">${external('https://parable-asia.com/guideline/','패러블 팬 제작 콘텐츠 가이드라인')}${external('https://berriz.in/ko/isegyeidol/notice/','베리즈 공식 공지')}${external('https://cafe.naver.com/steamindiegame','왁물원 팬카페')}</div></section><section class="panel"><h2>함께 만드는 기록</h2><p class="muted">창작 기록은 원작자·공개일·원본 링크·소개 범위를 확인한 후 연결합니다. 팬 닉네임별 활동량이나 댓글 성향을 수집하지 않습니다.</p><p class="data-note">창작 제보·수정 요청 접수 서버는 이 검토 페이지에 연결되어 있지 않습니다. 개인정보나 비공개 자료를 입력하는 폼도 만들지 않았습니다.</p></section><section class="panel"><h2>공연·행사 준비</h2><p class="muted">일정의 원문과 예매·입장 안내를 확인하고 확정 일정만 캘린더에 저장하세요. 예매 일정과 공연 시작 시각은 별개입니다.</p><a class="text-link" href="#/schedule?kind=event">확인된 일정 보기 ${icon('arrow')}</a></section><section class="panel"><h2>응원법·세트리스트</h2><p class="muted">확인된 공개 자료가 준비되면 곡·행사 상세에 연결하는 구성입니다. 현재 없는 응원법·세트리스트를 만들어 넣지 않았습니다.</p>${badge('연결 자료 준비 전','warning')}</section></div>`;
 return heading('좋아하는 마음이 오래 가도록','입문·복귀·참여를 돕는 짧은 길잡이.','A GUIDE FOR EVERY FAN')+tabs([['start','입문·복귀'],['terms','자료 읽는 법'],['participate','참여·창작']],tab)+body;}
function settingsView(){return heading('나에게 맞는 화면','검토 페이지의 설정만 바뀝니다. 운영 계정이나 알림 서버에는 저장하지 않습니다.','PREFERENCES')+`<section class="panel"><div class="settings-row"><div><h3>색상 테마</h3><p>밝은 화면과 어두운 화면을 선택합니다.</p></div><select data-setting="theme" aria-label="색상 테마"><option value="dark" ${prefs.theme==='dark'?'selected':''}>어두운 화면</option><option value="light" ${prefs.theme==='light'?'selected':''}>밝은 화면</option></select></div><div class="settings-row"><div><h3>사진 자동 전환</h3><p>홈의 단체 사진을 약 10초마다 교체합니다. 사진 아래에는 조작부를 추가하지 않습니다.</p></div><label><input type="checkbox" data-setting="gallery" ${prefs.gallery?'checked':''}>켜기</label></div><div class="settings-row"><div><h3>영상 제목·이미지 가리기</h3><p>멤버 영상·다시보기 목록의 제목과 썸네일을 가립니다. 스포일러를 자동 판별하는 기능은 아닙니다.</p></div><label><input type="checkbox" data-setting="spoilers" ${prefs.spoilers?'checked':''}>가리기</label></div><div class="settings-row"><div><h3>영상·음악 목록 밀도</h3><p>큰 이미지 카드 또는 간단한 목록으로 봅니다.</p></div><select data-setting="density" aria-label="목록 밀도"><option value="cards" ${prefs.density==='cards'?'selected':''}>카드형</option><option value="list" ${prefs.density==='list'?'selected':''}>목록형</option></select></div></section><section class="panel section"><h2>관심 멤버</h2><p class="muted small">하나만 고르지 않아도 됩니다. 선택은 이 브라우저에서만 기억합니다.</p><div class="button-row">${D.members.map(m=>`<button class="chip tone-${m.id}" data-interest="${m.id}" aria-pressed="${prefs.interests.includes(m.id)}"><i class="dot"></i>${m.name}</button>`).join('')}</div></section><section class="panel section"><div class="badges">${badge('설계 검토 · 발송 미연결','warning')}</div><h2>새 공지·방송·일정 알림</h2><p class="muted">알림 서버, 중복 발송 방지와 취소·변경 처리는 운영 연결 전입니다. 아래 항목은 설정 흐름 검토용이며 실제 알림을 보내거나 브라우저 알림 권한을 요청하지 않습니다.</p><div class="settings-row"><div><h3>알림 설정 시안 펼치기</h3><p>이 브라우저에 시안 선택만 저장합니다.</p></div><label><input type="checkbox" data-setting="notifications" ${prefs.notifications?'checked':''}>펼치기</label></div>${prefs.notifications?`<div class="subtle"><p>제안 항목: 관심 멤버 공지 · 방송 시작 · 저장 일정 변경</p><p>제안 정책: 조용한 시간 · 중복 억제 · 수신 해제 · 출처 확인 후 발송</p><div class="button-row"><button class="button" disabled>실제 알림 발송 · 미연결</button><button class="button" disabled>기기 간 계정 동기화 · 미연결</button></div></div>`:''}</section><section class="panel section"><h2>검토용 저장정보</h2><p class="muted">저장한 자료·관심 멤버·직접 시청 표시·화면 설정만 관리합니다. 운영 사이트의 데이터·계정·세션은 변경하지 않습니다.</p><div class="button-row"><button class="button" data-action="export-saved">저장 목록 백업</button><button class="button" data-action="reset-review">이 검토본의 저장정보 지우기</button></div><p class="data-note">${storageAvailable?'브라우저 저장 사용 가능':'브라우저 영구 저장 불가 · 이 탭에서만 유지'}</p></section>`;}
function statusView(){return heading('자료가 언제 확인됐는지','배치 성공, 원본 확인, 화면 반영을 별개로 살펴봅니다.','SOURCE HEALTH')+`<div class="notice-box"><strong>운영 관리자 대시보드가 아닌 읽기 전용 검토 화면입니다.</strong><br>아래 상태는 저장된 스냅샷의 상태이며 현재 배치의 성공·실패를 실시간으로 조회한 것이 아닙니다. API 키·계정·세션·서버 경로는 표시하지 않습니다.</div><div class="grid two"><div class="panel"><p class="eyebrow">NOTICE SNAPSHOT</p><h2>${dateText(D.snapshotAt)}</h2><p class="muted small">일정 자료 생성 ${stamp(D.snapshotAt)}</p><p>등록 공지 ${D.notices.length.toLocaleString('ko-KR')}건 · 일정 ${D.events.length}건</p></div><div class="panel"><p class="eyebrow">VIDEO SNAPSHOT</p><h2>${dateText(D.scope.videoCheckedAt)}</h2><p class="muted small">일반 영상 기준 시각입니다. 개별 공식 영상은 별도 확인 자료를 사용합니다.</p><p>통합 영상 ${D.videos.length}개 · 자료 범위 제한 있음</p></div></div><section class="section">${sectionHead('출처별 마지막 확인','정상 게시와 전체 원본 수집 완료는 같은 뜻이 아닙니다.')}<div class="status-list">${D.sources.map(s=>`<article class="panel status-item"><div><h3>${esc(sourceNames[s.id]||s.label||s.id)}</h3><p class="small">마지막 원본 확인 ${stamp(s.lastSuccessAt)}<br>마지막 시도 ${stamp(s.lastAttemptAt)}</p></div><div>${badge(s.state==='ok'?'저장 시점 확인 성공':s.state==='snapshot'?'기존 확인 자료':s.state==='restricted'?'공개 등록 제외':'당시 미완료',s.state==='ok'?'good':'warning')}<p class="small">현재 상태는 운영 원본 재조회 필요</p></div></article>`).join('')}</div></section><section class="section panel"><h2>운영 연동 시 구분할 항목</h2><div class="scope-table-wrap"><table class="scope-table"><thead><tr><th>확인 항목</th><th>검토 기준</th><th>현재 검토본</th></tr></thead><tbody><tr><td>서버 게시 결과</td><td>업로드 후 읽기 일치</td><td>기존 운영 배치를 변경하지 않습니다.</td></tr><tr><td>출처 수집 완료</td><td>최종 성공 시각·누락 구간</td><td>기존 스냅샷의 상태만 읽습니다.</td></tr><tr><td>일반 영상 독립 갱신</td><td>단체·멤버·다시보기별 수집</td><td>통합 목록 화면 구현, 별도 서버 배치 연결 전입니다.</td></tr><tr><td>신규·수정·삭제·보류</td><td>근거와 변경 이력 보존</td><td>실제 건수를 측정한 척하지 않습니다.</td></tr></tbody></table></div></section>`;}
