function reviewView(){return `<section class="panel scope-hero"><div><p class="eyebrow">FIRST REVIEW · FEATURE/REVIEW-1ST</p><h1>기록을 더하는 것보다,<br>기록을 이어주는 아카이브.</h1><p>전체 개선안의 화면과 탐색 흐름을 한곳에서 확인하는 1차 검토입니다. 운영 화면을 바꾸지 않고, 기존 검증 자료를 사용해 클릭 가능한 흐름을 구성했습니다.</p><div class="button-row"><a class="button primary" href="#/home">검토 시작하기 ${icon('arrow')}</a><a class="button" href="#/search?q=%EB%A6%B4%ED%8C%8C+11%EC%9B%94+3%EC%9D%BC">날짜·멤버 검색 체험</a></div></div><div class="scope-count"><div><strong>6</strong><small>상위 메뉴 유지</small></div><div><strong>7</strong><small>자료 종류 통합검색</small></div><div><strong>6</strong><small>멤버별 모아보기</small></div><div><strong>01</strong><small>분리된 검토 버전</small></div></div></section><section class="section">${sectionHead('이 순서로 확인해 보세요','모든 링크는 이 검토 페이지 안에서 이어집니다.')}<div class="grid">${[['01','오늘의 이세돌','LIVE와 공식 소식, 최근 콘텐츠의 균형','#/home'],['02','놓친 공지 찾기','11월 3일 공지와 날짜별 목록','#/schedule?month=2026-11&date=2026-11-03&view=calendar'],['03','멤버를 중심으로 보기','프로필에서 소식·영상·음악·활동까지','#/member/lilpa'],['04','곡에서 음반으로','RE:WIND의 원본·음반·활동 연결','#/song/rewind'],['05','놓친 영상 이어보기','다시보기와 공식 공연 모아보기','#/live?tab=replay'],['06','내 저장함과 설정','자료 저장·시청 표시·사진 정지·스포일러 가림','#/saved']].map(([n,t,d,h])=>`<a class="series-card" href="${h}"><p class="eyebrow">REVIEW ${n}</p><h3>${t}</h3><p>${d}</p><span class="text-link">확인하기 ${icon('arrow')}</span></a>`).join('')}</div></section><section class="section">${sectionHead('전체 범위 적용 상태','화면 동작, 검증 자료의 한계, 서버 연동 전 항목을 구분합니다.')}<div class="panel"><table class="scope-table"><thead><tr><th>영역</th><th>상태</th><th>검토 내용</th></tr></thead><tbody>${scopeRows.map(([a,b,c])=>`<tr><td>${a}</td><td>${badge(b,b==='동작 구현'||b==='적용'?'good':'warning')}</td><td>${c}</td></tr>`).join('')}</tbody></table></div></section><section class="panel section prose"><h2>검토본을 읽는 기준</h2><p>자료는 기존 공개·검증 목록을 재사용합니다. 공지·일정 스냅샷 생성 시각은 ${stamp(D.snapshotAt)}이며, 음악·일반 영상은 각 자료의 별도 확인 시각을 유지합니다. 제작 시각을 원본의 최신 확인 시각으로 바꾸지 않았습니다.</p><p>미연결 기능을 운영 중인 것처럼 표현하지 않습니다. 알림 발송, 계정 동기화, 자동 캘린더 구독, 전체 방송 선곡표, 원문 수정 이력과 창작물 수집은 실제 운영 연결 전입니다.</p><p>이 파일은 공개 배포 미러가 아닙니다. 운영 접근 정책을 우회하는 호스팅을 추가하지 않으며, 기존 로그인·수집·음악·LIVE 정책은 그대로 둡니다.</p></section>`;}
function notFound(){return heading('찾을 수 없는 기록입니다','주소가 잘못되었거나 이 검토본에 포함되지 않은 항목입니다.')+empty('다른 기록을 찾아보세요','없는 항목을 비슷한 자료로 자동 대체하지 않습니다.','#/search','통합검색으로 이동');}

let cleanupGallery=()=>{},renderedHash='',scrollPositions=new Map(),composing=false;
function mountGallery(){cleanupGallery();const frame=document.querySelector('.gallery');if(!frame)return;const im=frame.querySelector('img');let index=0,timer,dead=false,generation=0;const motion=matchMedia('(prefers-reduced-motion: reduce)');
 const schedule=()=>{clearTimeout(timer);frame.dataset.autoplay=prefs.gallery&&!document.hidden?'playing':'paused';if(prefs.gallery&&!document.hidden&&!dead)timer=setTimeout(advance,10000);};
 async function advance(){const token=++generation;for(let tries=0;tries<D.gallery.length;tries++){const next=(index+tries+1)%D.gallery.length,candidate=new Image();candidate.src=D.gallery[next].src;try{await candidate.decode();}catch{continue;}if(dead||document.hidden||token!==generation)return;index=next;im.src=candidate.src;im.alt=D.gallery[index].alt;frame.dataset.index=String(index);break;}schedule();}
 const visible=()=>{generation++;schedule();};document.addEventListener('visibilitychange',visible);cleanupGallery=()=>{dead=true;generation++;clearTimeout(timer);document.removeEventListener('visibilitychange',visible);};schedule();
}
function paintLive(){const region=document.getElementById('live-region');if(region)region.innerHTML=liveSummaryHtml();const cards=document.getElementById('live-cards');if(cards)cards.innerHTML=liveCardsHtml(route().params);}
async function refreshLive(force=false){if(document.hidden||liveBusy||!['home','live'].includes(route().parts[0])||(route().parts[0]==='live'&&!['now',null].includes(route().params.get('tab'))))return;if(Date.now()-liveAttempt<10000)return;liveBusy=true;liveAttempt=Date.now();paintLive();try{liveRows=await Promise.all(LIVE_CHANNELS.map(async m=>{try{return await fetchLiveMember(m);}catch{return liveEmpty(m,'unavailable');}}));}finally{liveBusy=false;paintLive();}}
function render(){const r=route(),root=r.parts[0];cleanupGallery();document.documentElement.dataset.theme=prefs.theme;document.getElementById('app').innerHTML=shell();let html;
 if(root==='home')html=homeView(r.params);else if(root==='members')html=membersView();else if(root==='member'||root==='record')html=memberView(r.parts[1],r.params);else if(root==='schedule')html=scheduleView(r.params);else if(root==='notice')html=noticeView(r.parts[1]);else if(root==='event')html=eventView(r.parts[1]);else if(root==='music')html=musicView(r.params);else if(root==='song')html=songView(r.parts[1]);else if(root==='album')html=albumView(r.parts[1]);else if(root==='live')html=liveView(r.params);else if(root==='video')html=videoView(r.parts[1]);else if(root==='series')html=seriesView(r.parts[1]);else if(root==='history')html=r.parts[1]?historyDetail(r.parts[1]):historyView(r.params);else if(root==='search')html=searchView(r.params);else if(root==='saved')html=savedView(r.params);else if(root==='guide')html=guideView(r.params);else if(root==='settings')html=settingsView();else if(root==='status')html=statusView();else if(root==='review'||root==='about')html=reviewView();else html=notFound();
 document.getElementById('main').innerHTML=html;document.title=(document.querySelector('h1')?.textContent||'ISEGYE!')+' · 1차 검토';renderedHash=location.hash;mountGallery();refreshLive();
}
function updateSaveButtons(){document.querySelectorAll('[data-save]').forEach(b=>{const on=prefs.favorites.includes(b.dataset.save),r=registry.get(b.dataset.save);b.setAttribute('aria-pressed',String(on));b.setAttribute('aria-label',(b.closest('.spoiler-masked')?'가림 영상':r?.title||'자료')+' '+(on?'저장 해제':'저장'));b.innerHTML=icon('heart')+'<span>'+(on?'저장됨':'저장')+'</span>';});document.querySelectorAll('[data-save-count]').forEach(x=>x.textContent=prefs.favorites.filter(k=>registry.has(k)).length);}
function download(name,content,type){const blob=new Blob([content],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);}
document.addEventListener('click',async event=>{
 const save=event.target.closest('[data-save]');if(save){const key=save.dataset.save;if(!registry.has(key))return;const on=prefs.favorites.includes(key);prefs.favorites=on?prefs.favorites.filter(x=>x!==key):[key,...prefs.favorites];persist();if(route().parts[0]==='saved'){const y=scrollY;render();scrollTo(0,y);}else updateSaveButtons();toast(on?'저장함에서 제거했습니다.':storageAvailable?'이 브라우저의 검토용 저장함에 담았습니다.':'이 탭의 저장함에 담았습니다.');return;}
 const interest=event.target.closest('[data-interest]');if(interest){const id=interest.dataset.interest;if(!persons.has(id))return;prefs.interests=prefs.interests.includes(id)?prefs.interests.filter(x=>x!==id):[...prefs.interests,id];persist();const y=scrollY;render();scrollTo(0,y);toast('관심 멤버 설정을 반영했습니다.');return;}
 const watched=event.target.closest('[data-watched]');if(watched){const key=watched.dataset.watched;if(!registry.has(key))return;prefs.watched=prefs.watched.includes(key)?prefs.watched.filter(x=>x!==key):[...prefs.watched,key];persist();const y=scrollY;render();scrollTo(0,y);return;}
 const reveal=event.target.closest('[data-reveal]');if(reveal){const card=reveal.closest('article');card.classList.remove('spoiler-masked');card.querySelector('[data-spoiler-title]')?.removeAttribute('aria-label');card.querySelector('h3')?.removeAttribute('aria-hidden');updateSaveButtons();reveal.remove();return;}
 const ics=event.target.closest('[data-ics]');if(ics){try{const row=events.get(ics.dataset.ics);download('isegye-'+row.date+'.ics',makeCalendar(row),'text/calendar;charset=utf-8');toast('확정 일정 파일을 저장합니다. 자동 동기화는 아닙니다.');}catch{toast('이 일정은 확정된 내보내기 대상이 아닙니다.');}return;}
 if(event.target.closest('[data-copy]')){try{await navigator.clipboard.writeText(location.href);toast(location.protocol==='file:'?'이 파일 안의 기록 주소를 복사했습니다. 다른 기기에서는 검토 파일이 필요합니다.':'기록 주소를 복사했습니다.');}catch{toast('자동 복사를 사용할 수 없습니다. 주소창의 주소를 복사해 주세요.');}return;}
 const action=event.target.closest('[data-action]')?.dataset.action;
 if(action==='theme'){prefs.theme=prefs.theme==='dark'?'light':'dark';persist();document.documentElement.dataset.theme=prefs.theme;document.querySelectorAll('[data-action=theme]').forEach(b=>b.innerHTML=icon(prefs.theme==='dark'?'sun':'moon'));}
 if(action==='more'){const el=document.getElementById('more-menu'),on=el.classList.toggle('open');document.querySelector('[data-action=more]').setAttribute('aria-expanded',String(on));}
 if(action==='refresh-live'){if(Date.now()-liveAttempt<10000){toast('중복 조회를 줄이기 위해 잠시 후 다시 확인해 주세요.');return;}refreshLive(true);}
 if(action==='export-saved'){const data={schemaVersion:1,scope:'isegye-review-1st-browser-only',exportedAt:new Date().toISOString(),items:prefs.favorites.map(k=>registry.get(k)).filter(Boolean).map(r=>({key:r.key,title:r.title,route:itemRoute(r),source:safeExternal(r.url)}))};download('isegye-review1-saved.json',JSON.stringify(data,null,2),'application/json');}
 if(action==='reset-review'&&confirm('이 검토 페이지의 저장 목록·관심 멤버·설정만 삭제할까요? 운영 사이트의 저장정보는 변경하지 않습니다.')){prefs={...defaults,favorites:[],interests:[],watched:[]};try{localStorage.removeItem('isegye:review1:prefs');localStorage.removeItem('isegye:review1:lastVisit');}catch{}render();toast('검토용 저장정보만 지웠습니다.');}
});
document.addEventListener('change',event=>{
 const setting=event.target.dataset.setting;if(setting&&Object.hasOwn(defaults,setting)){prefs[setting]=event.target.type==='checkbox'?event.target.checked:event.target.value;persist();const y=scrollY;render();scrollTo(0,y);return;}
 const key=event.target.dataset.filter;if(key){const obj={[key]:event.target.value};if(key==='month')obj.date=null;location.hash=patch(obj);}
});
document.addEventListener('compositionstart',()=>{composing=true;});document.addEventListener('compositionend',()=>{composing=false;});
document.addEventListener('keydown',event=>{const editing=/^(INPUT|TEXTAREA|SELECT)$/.test(event.target.tagName)||event.target.isContentEditable;if(event.key==='Enter'&&editing&&(event.isComposing||composing||event.keyCode===229))event.preventDefault();if(event.key==='/'&&!editing&&!event.ctrlKey&&!event.metaKey){event.preventDefault();document.getElementById('header-query')?.focus();}if(event.key==='Escape'){document.getElementById('more-menu')?.classList.remove('open');document.querySelector('[data-action=more]')?.setAttribute('aria-expanded','false');}});
document.addEventListener('submit',event=>{const form=event.target;if(!form.matches('#header-search,#global-search,[data-query-form]'))return;event.preventDefault();if(composing)return;const q=String(new FormData(form).get('q')||'').trim().slice(0,180);if(form.id==='header-search'){if(!q){form.querySelector('input').focus();return;}const target=url('search',{q});if(location.hash===target){document.getElementById('main').focus();}else location.hash=target;}else location.hash=patch({q,page:null});});
document.addEventListener('error',event=>{const im=event.target;if(im instanceof HTMLImageElement&&im.matches('[data-thumbnail]'))im.hidden=true;},true);
window.addEventListener('hashchange',event=>{if(location.hash==='#main'){document.getElementById('main')?.focus();return;}const old=event.oldURL.split('#')[1]||'',next=event.newURL.split('#')[1]||'';scrollPositions.set('#'+old,scrollY);const same=old.split('?')[0]===next.split('?')[0];const pos=scrollPositions.has('#'+next)?scrollPositions.get('#'+next):same?scrollY:0;render();requestAnimationFrame(()=>{scrollTo(0,pos);if(!same)document.getElementById('main').focus({preventScroll:true});});});
setInterval(()=>{if(!document.hidden){paintLive();refreshLive();}},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshLive();});
if(!location.hash)history.replaceState(null,'','#/home');render();
